{
  "name": "self-improving-opencode",
  "version": "0.3.0",
  "description": "Portable self-improving skill lifecycle with an OpenCode-native review loop.",
  "type": "module",
  "exports": {
    ".": "./dist/adapters/opencode/index.js",
    "./core": "./dist/core/index.js"
  },
  "types": "./dist/adapters/opencode/index.d.ts",
  "bin": {
    "self-improving-ai": "dist/cli.js",
    "self-improving-opencode": "dist/cli.js"
  },
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json && mkdir -p plugins/claude-code/runtime plugins/self-improving/runtime && bun build src/host-worker.ts --target=node --outfile=plugins/claude-code/runtime/host-worker.js && cp plugins/claude-code/runtime/host-worker.js plugins/self-improving/runtime/host-worker.js && cp adapters/shared/stop_hook.py plugins/claude-code/adapters/shared/stop_hook.py && cp adapters/shared/stop_hook.py plugins/self-improving/adapters/shared/stop_hook.py",
    "check": "tsc -p tsconfig.json --noEmit",
    "test": "bun test src && python3 -m unittest adapters/shared/test_stop_hook.py",
    "prepack": "bun run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent-skills",
    "self-improving"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/hueyexe/self-improving-ai.git"
  },
  "homepage": "https://github.com/hueyexe/self-improving-ai#readme",
  "bugs": "https://github.com/hueyexe/self-improving-ai/issues",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.23",
    "@types/node": "24.3.0",
    "typescript": "7.0.2"
  }
}
